{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate as select \'Uniware\' as source ,Date(order_date) as Order_date ,sku ,marketplace ,case when marketplace =\'MEESHO_BLR\' then \'SR-Banglore\' when marketplace =\'MEESHO_GGN\' then \'SR-Gurgoan\' when marketplace =\'MEESHO_MUM\' then \'SR-Mumbai\' when marketplace =\'FIRSTCRY_MUM\' then \'SR-Mumbai\' when marketplace =\'SHOPIFY_MUM\' then \'SR-Mumbai\' when marketplace =\'SMYTTEN_MUM\' then \'SR-Mumbai\' when marketplace =\'AMAZON_FLEX_API_MUM\' then \'SR-Mumbai\' when marketplace =\'AMAZON_FLEX_API_BLR\' then \'SR-Banglore\' when marketplace =\'AMAZON_FLEX_API_GGN\' then \'SR-Gurgoan\' when marketplace =\'AMAZON_FLEX_API_KOL\' then \'SR-Kolkata\' when marketplace =\'MYNTRAPPMP_GGN\' then \'SR-Gurgoan\' when marketplace =\'MYNTRAPPMP_BLR\' then \'SR-Banglore\' when marketplace =\'MYNTRAPPMP_MUM\' then \'SR-Mumbai\' when marketplace =\'MYNTRAPPMP_KOL\' then \'SR-Kolkata\' when marketplace =\'FLIPKART\' then \'SR-Kolkata\' when marketplace =\'FLIPKART_MUM\' then \'SR-Mumbai\' when marketplace =\'FLIPKART_GGN1\' then \'SR-Gurgoan\' when marketplace =\'FLIPKART_GGN\' then \'SR-Gurgoan\' when marketplace =\'FLIPKART_BLR\' then \'SR-Banglore\' when marketplace =\'AMAZON_IN_API\' then \'AMAZON\' when marketplace =\'CUSTOM\' then \'CUSTOM\' else marketplace end as Facility ,sum(cast(suborder_quantity as int64)) Units_Sold from hyuman-wh.maplemonk.hyuman_UNICOMMERCE_fact_items WHERE UPPER(order_status) != \'CANCELLED\' AND UPPER(sale_order_status) !=\'CANCELLED\' AND UPPER(shippingPackageStatus) NOT IN (\'RETURN_EXPECTED\',\'RETURNED\',\'RETURN_ACKNOWLEDGED\') group by 1,2,3,4,5 union all select shop_name as source ,Date(order_date) Order_date ,sku ,fulfilment_source as Marketplace ,case when fulfilment_source = \'malur_bts\' then \'FBF-Banglore\' when fulfilment_source = \'bhi_vas_wh_nl_01nl\' then \'FBF-Mumbai\' when fulfilment_source = \'ulub_bts\' then \'FBF-Kolkata\' when fulfilment_source = \'gur_san_wh_nl_01nl\' then \'FBF-Gurgoan\' else fulfilment_source end as Facility ,sum(cast(quantity as int64)) Units_sold from maplemonk.hyuman_flipkart_fact_items where UPPER(order_item_status) NOT IN(\'RETURNED\',\'CANCELLED\',\'RETURN REQUESTED\',\'UNDELIVERED\') and fulfilment_type = \'FBF\' group by 1,2,3,4,5 union all select \'Blinkit\' as source ,Date(order_date) Order_date ,commonsku as sku ,\'Blinkit\' as Marketplace ,\'Blinkit\' as Facility ,sum(cast(quantity as int64)) as Units_sold from MapleMonk.Hyuman_Blinkit_Fact_items where UPPER(order_status) !=\'CANCELLED\' group by 1,2,3,4,5 Union all select \'Eshopbox\' as source, date(order_date) as Order_date, sku, marketplace, CASE WHEN LOWER(warehouse_name) = \'eshopbox_gurgaon_fc3\' THEN \'Eshopbox-Gurgaon\' WHEN LOWER(warehouse_name) = \'eshop_xmum2\' THEN \'Eshopbox-Mumbai\' WHEN LOWER(warehouse_name) = \'accu\' THEN \'Eshopbox-Kolkata\' WHEN LOWER(warehouse_name) = \'eshop_bangaloresblr\' THEN \'Eshopbox-Bangalore\' ELSE warehouse_name END AS facility, sum(cast(suborder_quantity as int64)) as Units_sold from hyuman-wh.maplemonk.hyuman_ESHOPBOX_fact_items WHERE lower(marketplace) != \'unicommerce\' AND LOWER(sale_order_status) NOT IN ( \'cancelled\', \'return on the way\', \'return delivered\', \'quarantined\', \'return in processing\') group by 1,2,3,4,5; create or replace table maplemonk.Hyuman_Drr_Factitems as WITH daily_sales AS ( SELECT source, facility, sku, order_date, SUM(units_sold) AS daily_qty FROM Maplemonk.Hyuman_DRR_Sales_Consolidated_Intermediate WHERE order_date < CURRENT_DATE() GROUP BY 1,2,3,4 ), thresholds AS ( SELECT source, facility, sku, ROUND( SAFE_DIVIDE(SUM(daily_qty),COUNT(DISTINCT order_date)) / 2,2) AS threshold_avg FROM daily_sales WHERE order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) GROUP BY 1,2,3 ) SELECT d.source, d.facility, d.sku, t.threshold_avg AS average, ROUND( SAFE_DIVIDE(SUM( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) THEN d.daily_qty END), COUNT( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 7 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) AND d.daily_qty >= t.threshold_avg THEN 1 END)),2) AS drr_7, ROUND( SAFE_DIVIDE(SUM( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) THEN d.daily_qty END), COUNT( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 14 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) AND d.daily_qty >= t.threshold_avg THEN 1 END)),2) AS drr_14, ROUND( SAFE_DIVIDE(SUM( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) THEN d.daily_qty END), COUNT( CASE WHEN d.order_date BETWEEN DATE_SUB(CURRENT_DATE(), INTERVAL 28 DAY) AND DATE_SUB(CURRENT_DATE(), INTERVAL 1 DAY) AND d.daily_qty >= t.threshold_avg THEN 1 END)),2) AS drr_28 FROM daily_sales d JOIN thresholds t ON d.source = t.source AND d.facility = t.facility AND d.sku = t.sku GROUP BY 1,2,3,4;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

